    }
    int cols = grid[0].length;
    int[] parent = new int[cols];
    for (int i = 0; i < cols; i++) {
        parent[i] = i;
    }

    public int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) {
            parent[rootX] = rootY;
        }
    }

    for (int i = 0; i < cols; i++) {
        for (int j = 0; j < grid.length; j++) {
            if (grid[j][i] == '@') {
                if (i + 1 < cols && grid[j][i + 1] == '@') {
                    union(i, i + 1);
                }
                if (j + 1 < grid.length && grid[j + 1][i] == '@') {
                    union(i, i);
                }
            }
        }
    }

    java.util.HashSet<Integer> roots = new java.util.HashSet<>();
    for (int i = 0; i < cols; i++) {
        roots.add(find(i));
    }
    return roots.size();
}

