    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n) {
        return "cannot be travelled";
    }
    if (end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }
    if (paths == null) {
        return "can be travelled".equals("can be travelled") ? (start[0] == end[0] && start[1] == end[1] ? "can be travelled" : "cannot be travelled") : "cannot be travelled";
    }

    // If start equals end, we can travel trivially
    if (start[0] == end[0] && start[1] == end[1]) {
        return "can be travelled";
    }

    // Build adjacency list
    // Each node is represented by a pair (x, y)
    // We'll use a map from a node (encoded as int) to list of neighbors
    int totalNodes = n * n;
    List<List<Integer>> adj = new ArrayList<>(totalNodes);
    for (int i = 0; i < totalNodes; i++) {
        adj.add(new ArrayList<>());
    }

    for (int[] path : paths) {
        if (path == null || path.length < 4) {
            continue;
        }
        int x1 = path[0];
        int y1 = path[1];
        int x2 = path[2];
        int y2 = path[3];

        if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n) continue;
        if (x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) continue;

        int node1 = x1 * n + y1;
        int node2 = x2 * n + y2;

        adj.get(node1).add(node2);
        adj.get(node2).add(node1);
    }

    // BFS from start node
    int startNode = start[0] * n + start[1];
    int endNode = end[0] * n + end[1];

    boolean[] visited = new boolean[totalNodes];
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(startNode);
    visited[startNode] = true;

    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current == endNode) {
            return "can be travelled";
        }
        for (int neighbor : adj.get(current)) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                queue.offer(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

