public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        throw new IllegalArgumentException("Input strings cannot be null");
    }

    int commonCount = 0;
    char[] chars1 = word1.toUpperCase().toCharArray();
    char[] chars2 = word2.toUpperCase().toCharArray();
    boolean[] matched2 = new boolean[chars2.length];

    for (char c1 : chars1) {
        for (int j = 0; j < chars2.length; j++) {
            if (!matched2[j] && c1 == chars2[j]) {
                commonCount++;
                matched2[j] = true;
                break;
            }
        }
    }

    int totalLength = word1.length() + word2.length();
    String result;

    if (commonCount == 0) {
        result = "0";
    } else if (commonCount == totalLength) {
        result = "1";
    } else {
        int gcd = gcd(commonCount, totalLength);
        int numerator = commonCount / gcd;
        int denominator = totalLength / gcd;
        if (denominator == 1) {
            result = String.valueOf(numerator);
        } else {
            result = numerator + "/" + denominator;
        }
    }

    return "appx(" + word1 + ", " + word2 + ") = " + result;
}

public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        throw new IllegalArgumentException("Words cannot be null");
    }

    java.util.Map<Character, Integer> charCount = new java.util.HashMap<>();

    for (char c : word1.toCharArray()) {
        charCount.put(c, charCount.getOrDefault(c, 0) + 1);
    }

    int common = 0;
    for (char c : word2.toCharArray()) {
        Integer count = charCount.get(c);
        if (count != null && count > 0) {
            common++;
            charCount.put(c, count - 1);
        }
    }

    int sum = word1.length() + word2.length();
    if (sum == 0) {
        return String.format("appx(%s, %s) = 0", word1, word2);
    }

    int commonGCD = gcd(common, sum);
    int reducedCommon = commonGCD == 0 ? common : common / commonGCD;
    int reducedSum = commonGCD == 0 ? 1 : sum / commonGCD;

    if (reducedSum == 1) {
        return String.format("appx(%s, %s) = %d", word1, word2, reducedCommon);
    } else {
        return String.format("appx(%s, %s) = %d/%d", word1, word2, reducedCommon, reducedSum);
    }
}

public static String appx(String word1, String word2) {
