    String w2 = word2.toUpperCase();
    int count = 0;
    for (int i = 0; i < w1.length(); i++) {
        char c = w1.charAt(i);
        for (int j = 0; j < w2.length(); j++) {
            if (c == w2.charAt(j)) {
