public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }
    int common = 0;
    int[] count1 = new int[26];
    int[] count2 = new int[26];
    for (char c : word1.toCharArray()) {
        if (Character.isLetter(c)) {
            count1[Character.toUpperCase(c) - 'A']++;
        }
    }
    for (char c : word2.toCharArray()) {
        if (Character.isLetter(c)) {
            count2[Character.toUpperCase(c) - 'A']++;
        }
    }
    for (int i = 0; i < 26; i++) {
        common += Math.min(count1[i], count2[i]);
    }
    int sumLength = word1.length() + word2.length();
    if (sumLength == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }
    int g = gcd(common, sumLength);
    int numerator = common / g;
    int denominator = sumLength / g;
    if (denominator == 1) {
        return "appx(" + word1 + ", " + word2 + ") = " + numerator;
    } else {
        return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
    }
}

public static String convertDatesToWeekdays(String date) {
    if (date == null || date.trim().isEmpty()) {
        return "Invalid date format";
    }

    try {
        String[] parts = date.trim().split("\\s+");
        if (parts.length != 3) {
            return "Invalid date format";
        }

        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        if (month < 1 || month > 12) {
            return "Invalid date format";
        }
        if (day < 1 || day > 31) {
            return "Invalid date format";
        }

        java.util.Calendar calendar = java.util.Calendar.getInstance();
        calendar.clear();
        calendar.set(year, month - 1, day);

        if (!calendar.isSet(java.util.Calendar.SECOND) == false && day > java.time.YearMonth.of(year + 1, month).lengthOfMonth()) {
            return "Invalid date format";
        }

        // Validate the date using LocalDate
        try {
            java.time.LocalDate localDate = java.time.LocalDate.of(year, month, day);
        } catch (Exception e) {
            return "Invalid date format";
        }

        String[] monthNames = {"January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"};
        String[] dayNames = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};

        int weekdayIndex = calendar.get(java.util.Calendar.DAY_OF_WEEK);
        // Calendar: SUNDAY=1, MONDAY=2, ..., SATURDAY=7
        // Map to 0-6: Sunday=0, Monday=1, ..., Saturday=6
        int dayOfWeekIndex = weekdayIndex - 1;

        return monthNames[month - 1] + " " + day + ", " + year + " is a " + dayNames[dayOfWeekIndex];

    } catch (NumberFormatException e) {
        return "Invalid date format";
    } catch (Exception e) {
        return "Invalid date format";
    }
}

