public double trimMean(int[] arr) {
    if (arr == null) {
        return 0.0;
    }
    int n = arr.length;
    if (n == 0) {
        return 0.0;
    }
    int[] sorted = arr.clone();
    java.util.Arrays.sort(sorted);
    int k = n / 20;
    int start = k;
    int end = n - k;
    int count = end - start;
    if (count <= 0) {
        return 0.0;
    }
    long sum = 0;
    for (int i = start; i < end; i++) {
        sum += sorted[i];
    }
    return (double) sum / count;
}

public double trimMean(int[] arr) {
