    int[] sorted = arr.clone();
    Arrays.sort(sorted);

    int start = trimCount;
    int end = n - trimCount;

    if (start >= end) {
        return 0.0;
    }

    long sum = 0;
    for (int i = start; i < end; i++) {
        sum += sorted[i];
    }

    double count = end - start;
