        return 0.0;
    }

    int n = arr.length;
    int removeCount = n / 20;
    int trimmedLength = n - 2 * removeCount;

    // If array is too small to trim 5% from both ends, return the mean of all elements
    // Since the problem guarantees valid input, we proceed with the standard approach.

    // Make a copy and sort
    int[] sorted = arr.clone();
    java.util.Arrays.sort(sorted);

    double sum = 0.0;
    for (int i = removeCount; i < n - removeCount; i++) {
        sum += sorted[i];
    }

    return sum / trimmedLength;
}

