}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length == 0 || arr.length % 2 != 0 || k <= 0) {
        return false;
    }
    int[] counts = new int[k];
    for (int num : arr) {
        int mod = ((num % k) + k) % k;
        counts[mod]++;
    }
    if (counts[0] % 2 != 0) {
        return false;
    }
    for (int i = 1; i <= k / 2; i++) {
        if (i == k - i) {
            if (counts[i] % 2 != 0) {
                return false;
            }
        } else {
            if (counts[i] != counts[k - i]) {
                return false;
            }
        }
    }
    return true;
}

