    int[] remainders = new int[k];

    for (int num : arr) {
        int remainder = ((num % k) + k) % k;
        remainders[remainder]++;
    }

    // For remainder 0, count must be even
    if (remainders[0] % 2 != 0) {
        return false;
    }

    // For remainders i and k-i, counts must match
    for (int i = 1; i <= k / 2; i++) {
        if (i == k - i) {
            if (remainders[i] % 2 != 0) {
                return false;
            }
        } else {
            if (remainders[i] != remainders[k - i]) {
                return false;
            }
        }
    }

