public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        return false;
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false;
    }

    int[] freq = new int[k];
    for (int num : arr) {
        int mod = num % k;
        if (mod < 0) {
            mod += k;
        }
        freq[mod]++;
    }

    // For remainder 0, count must be even
    if (freq[0] % 2 != 0) {
        return false;
    }

    // For each remainder r (1 to k-1), we need freq[r] == freq[k-r]
    for (int r = 1; r < k / 2 + 1; r++) {
        int complement = k - r;
        if (r == complement) {
            // Only possible when k is even and r = k/2
            if (r * 2 == k) {
                if (freq[r] % 2 != 0) {
                    return false;
                }
            }
        } else {
            if (freq[r] != freq[complement]) {
                return false;
            }
        }
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (k <= 0) return false;
    if (arr.length % 2 != 0) return false;

    int[] count = new int[k];
    for (int num : arr) {
        int rem = num % k;
        if (rem < 0) rem += k;
        count[rem]++;
    }

    for (int i = 1; i <= k / 2; i++) {
        if (count[i] != count[k - i]) {
            return false;
        }
    }

    return count[0] % 2 == 0;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            adj.get(u).add(v);
            adj.get(v).add(u);
        }

        // DFS: returns the time needed to explore the subtree rooted at node
        // and return to its parent. If no apple in the subtree, returns 0.
        // We use a visited array to avoid going back to parent.
        boolean[] visited = new boolean[n];
        int[] result = new int[1];

        private int dfs(int node, int parent, List<List<Integer>> adj, boolean[] hasApple, boolean[] visited) {
            visited[node] = true;
            int total = 0;
            boolean subtreeHasApple = hasApple[node];

            for (int neighbor : adj.get(node)) {
                if (neighbor == parent) {
                    continue;
                }
                if (visited[neighbor]) {
                    continue;
                }

                int childTime = dfs(neighbor, node, adj, hasApple, visited);
                if (childTime > 0) {
                    total += childTime + 2;
                    subtreeHasApple = true;
                }
            }

            if (!subtreeHasApple && node != 0) {
                return 0;
            }
            return total;
        }

        return dfs(0, -1, adj, hasApple, visited);
    }

public int minTime(int n, int[][] edges, boolean[] hasApple) {
        if (n == 0) return 0;

