            adj.get(u).add(v);
            adj.get(v).add(u);
        }

        // Use DFS to find at each node:
        // - the time needed to collect apples in its subtree (including going down and coming back)
        // We'll compute this recursively.
        // We need to keep track of the parent to avoid going back.

        int[] time = new int[n]; // time[i] = time to collect apples in subtree rooted at i and return to i
        // Note: this "time" already includes the round-trip to children that have apples.

        // Prevent revisiting node 0's parent (which doesn't exist), so we use a visited set or parent tracking
        // Do DFS from node 0
        boolean[] visited = new boolean[n];
        dfs(0, -1, adj, hasApple, time, visited);

        return time[0];
    }

