public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) {
        return false;
    }
    // If one element is both smaller than the rest and larger than the rest, can't split.
    // More practically: if k=1 is possible, then we check if any single element equals the average.
    // The average of the whole array: totalSum / n
    // If a subset of size k has the same average, then subset sum = k * totalSum / n
    // This must be an integer. So k * totalSum must be divisible by n.

    int totalSum = 0;
    int minVal = Integer.MAX_VALUE;
    int maxVal = Integer.MIN_VALUE;
    for (int v : nums) {
        totalSum += v;
        if (v < minVal) minVal = v;
        if (v > maxVal) maxVal = v;
    }

    // Special check: if minVal + maxVal == 2 * (totalSum / n) but totalSum/n not integer, 
    // Actually a simpler necessary condition: if k*totalSum % n != 0, then no subset of size k works.

    // We iterate k from 1 to n/2 (since we can swap the two parts, only need to check up to n/2)
    // Actually, we need to check k from 1 to n-1, but k and n-k are symmetric. Check k from 1 to n/2.
    // But we must ensure that (totalSum * k) is divisible by n for subset sum to be integer.

    for (int k = 1; k <= n / 2; k++) {
        if (totalSum * k % n != 0) {
            continue;
        }
        int targetSum = totalSum * k / n;
        // Check if any subset of size k sums to targetSum.
        // Use set of possible sums for subsets of size k.
        // For k=1: check if any element equals targetSum.
        if (k == 1) {
            boolean found = false;
            for (int v : nums) {
                if (v == targetSum) {
                    found = true;
                    break;
                }
            }
            if (found) {
                return true;
            }
            continue;
        }

        // DP: possible sums for subsets of size k
        // Initialize: dp[0] = 0 (empty subset, size 0, sum 0). But we need subsets of exactly size k.
        // Let dp[j] be a set of possible sums for subsets of size j.
        // j ranges from 0 to k.

        // To avoid using too much memory and time, we can use a boolean array if the range of sums is bounded,
        // but sums can be large. Alternatively, use a Set for each j up to k.

        // Use a list of sets: sets[j] contains all possible sums of subsets of size j.
        Set<Integer> sets[] = new Set[k + 1];
        for (int i = 0; i <= k; i++) {
            sets[i] = new HashSet<>();
        }
        sets[0].add(0);

        for (int num : nums) {
            // Iterate j from k down to 1 to avoid using same element multiple times
            for (int j = k; j >= 1; j--) {
                Set<Integer> currentSet = new HashSet<>();
                for (int s : sets[j - 1]) {
                    int newSum = s + num;
                    currentSet.add(newSum);
                }
                sets[j].addAll(currentSet);
            }
        }

        if (sets[k].contains(targetSum)) {
            return true;
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) {
        return false;
    }
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    // For split into two non-empty parts with averages a/b and c/d where b+d=n
    // same average means sum1/(len1) = sum2/(len2)
    // sum1 * len2 = sum2 * len1
    // sum1 * len2 = (sum - sum1) * (n - len2)
    // sum1 * len2 = sum * (n - len2) - sum1 * (n - len2)
    // sum1 * len2 + sum1 * (n - len2) = sum * (n - len2)
    // sum1 * n = sum * (n - len2)
    // So sum must be divisible by n, and there must exist k in [1, n-1] such that sum*k % n == 0
    // Then we need to check if there is a subset of size k with sum = sum*k/n

    boolean[] can = null;
    // We limit the subset size to at most n/2 due to symmetry
    int maxK = n / 2;

    for (int k = 1; k <= maxK; k++) {
        if (sum * k % n != 0) {
            continue;
        }
        int targetSum = sum * k / n;
        if (can == null || can.length != targetSum) {
            can = new boolean[targetSum + 1];
        } else {
            // reset
            for (int i = 0; i < can.length; i++) {
                can[i] = false;
            }
        }
        can[0] = true;
        for (int num : nums) {
            for (int s = targetSum; s >= num; s--) {
                if (can[s - num]) {
                    can[s] = true;
                }
            }
        }
        if (can[targetSum]) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) {
        return false;
    }
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    // Average of whole array is sum/n
    // For a subset of size k, we need sum(subset) = k * sum / n
    // So k * sum must be divisible by n.
    // We only need to check k from 1 to n/2 (since if we find a subset of size k with the average,
    // the complement has size n-k with the same average, so we can restrict to smaller side)
    int g = gcd(sum, n);
    int reducedSum = sum / g;
    int reducedN = n / g;
    // k must be a multiple of reducedN for k*sum to be divisible by n
    // k must be between 1 and n-1, and we also restrict to k <= n/2
    for (int k = reducedN; k <= n / 2; k += reducedN) {
        int target = (int) ((long) k * sum / n);
        // Use DP: dp[i][j] = whether it is possible to get sum j using exactly i elements
        // But the sum can be large, so we use a bitset or set of achievable sums per size
        // Alternatively, use a bitset per element count
        // Let's use a set of Integer arrays or a boolean 2D array
        // Max sum is at most 10000*10000 = 1e8, too large for boolean array.
        // Use Set<Integer> for each count
        Set<Integer>[] dp = new HashSet[n + 1];
        for (int i = 0; i <= n; i++) {
            dp[i] = new HashSet<>();
        }
        dp[0].add(0);
        for (int num : nums) {
            // iterate from high to low to avoid using same element twice
            for (int i = n; i >= 1; i--) {
                for (int s : dp[i - 1]) {
                    dp[i].add(s + num);
                }
            }
        }
        if (dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) {
        return false;
    }

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    // We need to find a subset of size k (1 <= k <= n-1) such that subsetSum is a multiple of k
    // and sum - subsetSum is a multiple of n - k.
    // This is equivalent to subsetSum / k == sum / n, which means subsetSum * n == sum * k.
    // Alternatively, we can think: if there's a subset of size k with sum S, then the other
    // subset of size n-k has sum sum-S. We need S/k == (sum-S)/(n-k)
    // => S*(n-k) == (sum-S)*k
    // => S*n - S*k == sum*k - S*k
    // => S*n == sum*k
    // So S = sum * k / n. S must be an integer, so sum * k must be divisible by n.

    // For each possible k from 1 to n-1, check if sum * k is divisible by n.
    // If yes, then target sum S = sum * k / n.
    // Then check if there exists a subset of size k with sum S.

    // Since n can be up to 20, we can use a dynamic programming approach.
    // Let dp[i][j][s] = true if we can pick j elements from the first i elements to get sum s.
    // But the range of s can be large. The max sum is 20 * 20000 = 400000, which is manageable.

    // Alternatively, we can use a more memory-efficient approach: for each k, we can do a DP
    // on the sum dimension, tracking whether we can achieve sum s with exactly k elements.

    // Let's use a boolean array dp[sum+1] for each k, but we need to track the count of elements.
    // A common trick: for each possible sum, track the set of possible counts, but that's complex.

    // Since n is at most 20, we can try all k and for each k, do a DP with dimensions [n+1][maxSum+1]
    // but maxSum is 400000, which is too large for a 3D array.

    // Better approach: for each k, check if sum * k % n == 0. If yes, S = sum * k / n.
    // Then we need to find a subset of exactly k elements with sum S.
    // We can sort the array and use a DP with a HashSet or a bitset for sums.

    // Let's use a DP where dp[j] is a set of possible sums using j elements.
    // For j from 1 to k, we update dp[j] by adding nums[i] to all sums in dp[j-1].
    // The number of distinct sums is limited, and k is at most 19, n is at most 20.

    // But in the worst case, the number of distinct sums can be large. Let's use a boolean array of size (maxSum+1)
    // for each j, but we need to be careful about memory.

    // Actually, for n up to 20, maxSum is 400000. We can do for each k (1 to n/2, by symmetry k and n-k)
    // so we only need to check k from 1 to n/2.

    // For each valid k (where sum * k % n == 0), S = sum * k / n.
    // Check if S is within [k*minVal, k*maxVal].
    // Then do a DP: for each element, update a 2D boolean array dp[j][s] = true if we can pick j elements
    // to sum to s.

    // To save memory, we can use a 1D array of bitsets or just iterate.

    // Let's precompute min and max.
    int minVal = Integer.MAX_VALUE;
    int maxVal = Integer.MIN_VALUE;
    for (int num : nums) {
        minVal = Math.min(minVal, num);
        maxVal = Math.max(maxVal, num);
    }

    // Check k from 1 to n/2 (since k and n-k are symmetric)
    for (int k = 1; k <= n / 2; k++) {
        long prod = (long) sum * k;
        if (prod % n != 0) {
            continue;
        }
        long S = prod / n;
        // S must be an integer and within the possible range for k elements.
        if (S < k * minVal || S > k * maxVal) {
            continue;
        }
        if (S > 400000) {
            continue; // Should not happen with given constraints
        }

        // Now check if there's a subset of size k with sum S.
        // Use DP: dp[j][s] = true if we can pick j elements to sum to s.
        // We'll use a 2D boolean array, but to save memory, we can use a 1D array for each j
        // and iterate.

        boolean[][] dp = new boolean[k + 1][(int) S + 1];
        dp[0][0] = true;

        for (int num : nums) {
            // Iterate j from k-1 down to 0, and s from S-num down to 0
            for (int j = k - 1; j >= 0; j--) {
                for (int s = (int) S; s >= num; s--) {
                    if (dp[j][s - num]) {
                        dp[j + 1][s] = true;
                    }
                }
            }
        }

        if (dp[k][(int) S]) {
            return true;
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) {
        return false;
    }
    long sum = 0;
    for (int num : nums) {
        sum += num;
    }
    // If we can split into k and n-k elements with same average,
    // then k * sum == n * (sum of k elements)
    // So sum of k elements must be sum * k / n, which must be an integer.
    for (int k = 1; k <= n / 2; k++) {
        if (sum % k != 0) {
            continue;
        }
        long target = sum * k / n;
        // Check if a subset of size k sums to target
        // Use bitset or memo. Since n is at most 16 (assumed for reasonable problem), we can use DP.
        if (canPartition(nums, k, target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    if (cost.length == 1) {
        return cost[0];
    }

    int n = cost.length;
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;

    for (int i = 2; i <= n; i++) {
        dp[i] = Math.min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2]);
    }

    return dp[n];
}

