public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    if (cost.length == 1) {
        return cost[0];
    }

    int n = cost.length;
    // dp[i] represents the minimum cost to reach step i
    // We can reach step i from step i-1 or step i-2
    // But we don't pay cost for steps we end at for the final top (which is n)
    // We use dynamic programming with two variables to save space

    // Let's define:
    // prev2 = min cost to reach step i-2
    // prev1 = min cost to reach step i-1
    // curr = min cost to reach step i

    // Initial: 
    // cost to reach step 0 = cost[0] (we start by paying cost[0])
    // cost to reach step 1 = cost[1] (we start by paying cost[1])
    // But actually, the problem says you can start from index 0 or 1, meaning 
    // if you start at 0, you pay cost[0]. If you start at 1, you pay cost[1].

    // Let dp[i] = minimum cost to reach step i (including the cost of step i if i < n)
    // For reaching the top (step n), the cost is 0
    // dp[0] = cost[0]
    // dp[1] = cost[1]
    // for i from 2 to n:
    //   if i < n:
    //       dp[i] = cost[i] + min(dp[i-1], dp[i-2])
    //   else:
    //       dp[i] = 0 + min(dp[i-1], dp[i-2])

    // We can iterate from 2 to n
    int prev2 = cost[0];
    int prev1 = cost[1];

    for (int i = 2; i <= n; i++) {
        int curr;
        if (i < n) {
            curr = cost[i] + Math.min(prev1, prev2);
        } else {
            curr = Math.min(prev1, prev2);
        }
        prev2 = prev1;
        prev1 = curr;
    }

    return prev1;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Cost array must not be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return Math.min(cost[0], 0);
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        dp[i] = Math.min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2]);
    }
    return dp[n];
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    if (cost.length == 1) {
        return cost[0];
    }

    int n = cost.length;
    int prev2 = 0;
    int prev1 = 0;

    for (int i = 0; i <= n; i++) {
        int current;
        if (i == 0 || i == 1) {
            current = 0;
        } else {
            int costPrev1 = (i - 1 < n) ? cost[i - 1] : 0;
            int costPrev2 = (i - 2 < n) ? cost[i - 2] : 0;
            current = Math.min(prev1 + costPrev1, prev2 + costPrev2);
        }
        prev2 = prev1;
        prev1 = current;
    }

    return prev1;
}

