public boolean hasAllCodes(String s, int k) {
    if (s == null || s.isEmpty()) {
        return k == 0;
    }
    if (k == 0) {
        return true;
    }
    if (s.length() < k) {
        return false;
    }

    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int count = 0;

    // First window
    int mask = 0;
    for (int i = 0; i < k; i++) {
        char c = s.charAt(i);
        mask = (mask << 1) | (c - '0');
    }
    if (!seen[mask]) {
        seen[mask] = true;
        count++;
    }

    // Slide the window
    for (int i = k; i < s.length(); i++) {
        char c = s.charAt(i);
        mask = ((mask << 1) & (total - 1)) | (c - '0');
        if (!seen[mask]) {
            seen[mask] = true;
            count++;
        }
    }

    return count == total;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.isEmpty() || k < 0 || k > s.length()) {
        return false;
    }

    int totalRequired = 1 << k;
    if (k == 0) {
        return true;
    }

    boolean[] seen = new boolean[totalRequired];
    int seenCount = 0;
    int mask = totalRequired - 1;
    int currentValue = 0;

    for (int i = 0; i < s.length(); i++) {
        currentValue = ((currentValue << 1) | (s.charAt(i) - '0')) & mask;
        if (i >= k - 1) {
            if (!seen[currentValue]) {
                seen[currentValue] = true;
                seenCount++;
                if (seenCount == totalRequired) {
                    return true;
                }
            }
        }
    }

    return seenCount == totalRequired;
}

