    }

    int totalCombinations = 1 << k;
    boolean[] seen = new boolean[totalCombinations];
    int count = 0;

    for (int i = 0; i <= s.length() - k; i++) {
        int code = 0;
        for (int j = 0; j < k; j++) {
            code = (code << 1) | (s.charAt(i + j) - '0');
        }
        if (!seen[code]) {
            seen[code] = true;
            count++;
            if (count == totalCombinations) {
                return true;
            }
        }
    }

    return false;
}

