    }
    if (k == 0) {
        return true;
    }
    if (s.length() < k) {
        return false;
    }
    int total = (int) Math.pow(2, k);
    if (total > s.length() - k + 1) {
        return false;
    }
    Set<Integer> seen = new HashSet<>();
    int mask = total - 1;
    int curr = 0;
    for (int i = 0; i < s.length(); i++) {
        curr = ((curr << 1) | (s.charAt(i) - '0')) & mask;
        if (i >= k - 1) {
            seen.add(curr);
            if (seen.size() == total) {
                return true;
            }
        }
    }
    return seen.size() == total;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < k) {
        return false;
    }
    if (k == 0) {
        return true;
    }
    int n = 1 << k; // 2^k
    boolean[] seen = new boolean[n];
    int count = 0;
    // Use a sliding window to compute the integer value of the current k-length substring
    // To avoid recomputing the whole window every time, maintain a bitmask
    // We can compute the value as we slide: 
    // Let window value be represented in k bits.
    // When sliding, we drop the most significant bit and shift left, then add the new bit.
    // But note: for k larger than Integer.MAX_VALUE bit length? No, k is up to 20 typically.
    // We'll compute the initial window, then slide.
    int window = 0;
    // First window
    for (int i = 0; i < k; i++) {
        window = (window << 1) | (s.charAt(i) - '0');
    }
    if (!seen[window]) {
        seen[window] = true;
        count++;
    }
    if (count == n) {
        return true;
    }
    // Slide the window
    // The mask to keep only k bits: (1 << k) - 1
    int mask = (1 << k) - 1;
    for (int i = k; i < s.length(); i++) {
        // Shift left, and add the new bit
        window = ((window << 1) | (s.charAt(i) - '0')) & mask;
        if (!seen[window]) {
            seen[window] = true;
            count++;
        }
        if (count == n) {
            return true;
        }
    }
    return false;
}

