                insertions++;
            }
        }
    }

    insertions += openCount;
    return insertions;
}

public int minOperations(int n) {
    // The array is arr[i] = 2*i + 1 for i in [0, n-1]
    // To make all elements equal, we move elements toward the median.
    // Since the array is sorted and has length n:
    // - If n is even, the median can be any value between arr[n/2 - 1] and arr[n/2]
    // - If n is odd, the median is arr[n/2]
    // 
    // For this specific arithmetic progression, the target value is the median.
    // The minimum number of operations equals the sum of absolute differences
    // from the median, but since each operation moves one unit, and we can
    // think of it as: total excess above median = total deficit below median = operations.
    //
    // Actually, the minimum number of operations is the sum of all positive
    // differences from the median (or equivalently, the sum of all absolute
    // differences divided by 2, since each operation transfers one unit).
    //
    // But wait: each operation moves one unit from one element to another,
    // so the total number of operations is the total amount that needs to be moved
    // from above-median elements to below-median elements, which equals the sum
    // of (arr[i] - median) for all i where arr[i] > median.
    //
    // For this specific problem, there's a known formula. Let's compute it directly.

    int left = 0;
    int right = n - 1;
    int operations = 0;

    while (left < right) {
        int valLeft = 2 * left + 1;
        int valRight = 2 * right + 1;
        int diff = valRight - valLeft;
        operations += diff;
        left++;
        right--;
    }

    return operations;
}

public int minOperations(int n) {
    return n % 2 == 0 ? (n / 2) * (n / 2) : (n / 2) * (n / 2 + 1);
}

public int minOperations(int n) {
    if (n <= 0) {
        return 0;
    }

    // The average of the array [1, 3, 5, ..., 2n-1] is n
    // The target value for each element to make them all equal is n

    // For even n: n = 2k
    // The array is [1, 3, 5, ..., 2n-1]
    // We need to reduce elements > n and increase elements < n
    // Elements less than n: 1, 3, 5, ..., (n-1) [for n even, n-1 is odd]
    // The sum of reductions needed for first k elements (where k = n/2)
    // For index i (0-based), current value is 2i+1, target is n
    // Reduction needed for elements where 2i+1 > n, i.e., i >= (n-1)/2
    // For even n, n/2 elements are above average, n/2 elements are below

    // Let's compute: for i from 0 to n-1:
    // If arr[i] < n, we need to add (n - arr[i]) to it
    // If arr[i] > n, we need to subtract (arr[i] - n) from it
    // Total operations = sum of all positive differences (which equals sum of all negative differences in magnitude)

    // Since the array is symmetric around n when n is odd, and we can pair them up
    // For I/O efficiency, let's use the formula

    // The number of operations is the sum of (n - arr[i]) for all i where arr[i] < n
    // Which is the same as the sum of (arr[i] - n) for all i where arr[i] > n

    // Let's verify with examples:
    // n = 3: arr = [1, 3, 5], target = 3
    // Elements < 3: 1, difference = 2
    // Elements > 3: 5, difference = 2
    // Total operations = 2 (we only count one side, since each move transfers 1 unit)

    // n = 6: arr = [1, 3, 5, 7, 9, 11], target = 6
    // Elements < 6: 1 (diff 5), 3 (diff 3), 5 (diff 1) -> sum = 9
    // Elements > 6: 7 (diff 1), 9 (diff 3), 11 (diff 5) -> sum = 9
    // Total operations = 9

    // So for each element below target, we add the difference; this equals the total operations
    long operations = 0;
    int target = n;
    for (int i = 0; i < n; i++) {
        int val = 2 * i + 1;
        if (val < target) {
            operations += (target - val);
        }
    }

    return (int) operations;
}

public int minOperations(int n) {
    // The array is [1, 3, 5, ..., 2n-1]
    // The sum of the array is n^2
    // The target value for all elements to be equal is n^2 / n = n
    // We need to compute the minimum number of operations to make all elements equal to n.
    // Each operation transfers 1 unit from one element to another.
    // The total "excess" that needs to be moved equals the sum of positive deviations from n (which equals sum of negative deviations in absolute value).
    // For arr[i] = 2*i + 1, deviation from n is (2*i + 1 - n).
    // We sum the positive deviations (for i where 2*i + 1 > n).

    // Let's find the threshold: 2*i + 1 > n  =>  i >= (n)/2
    // If n is even, n = 2k, then i >= k. Indices k, k+1, ..., n-1 are above n-1? Wait, n = 2k, target = 2k.
    // arr[i] = 2*i + 1. For i = k, arr[k] = 2k+1 > 2k = n. So starting from i = n/2 (when n even), values are above n.
    // If n is odd, n = 2k+1, target = 2k+1. arr[i] = 2*i+1. For i = k, arr[k] = 2k+1 = n. For i = k+1, arr[k+1] = 2k+3 > n.
    // So in general, we sum (2*i + 1 - n) for all i such that 2*i + 1 > n.

    int operations = 0;
    for (int i = 0; i < n; i++) {
        int val = 2 * i + 1;
        if (val > n) {
            operations += val - n;
        }
    }
    return operations;
}

