public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }

    // Generate Fibonacci numbers up to k
    List<Integer> fibs = new ArrayList<>();
    fibs.add(1);
    fibs.add(2); // We can think of F1=1, F2=1, but for greedy selection we use distinct sequence 1, 2, 3, 5, 8...
    // Actually, the standard Fibonacci used for this problem is 1, 1, 2, 3, 5, 8, 13...
    // But since greedy works with the sequence, let's generate properly.

    // Let's regenerate properly: F1=1, F2=2 (to avoid duplicate 1s which don't help in minimum count)
    // Actually, using 1, 2, 3, 5, 8... is standard for this greedy approach.

    // Clear and regenerate
    fibs.clear();
    fibs.add(1);
    fibs.add(2);

    int a = 1, b = 2;
    while (true) {
        int next = a + b;
        if (next > k) {
            break;
        }
        fibs.add(next);
        a = b;
        b = next;
    }

    // Greedy: pick largest Fibonacci number <= remaining k
    int count = 0;
    int remaining = k;
    for (int i = fibs.size() - 1; i >= 0; i--) {
        if (fibs.get(i) <= remaining) {
            count++;
            remaining -= fibs.get(i);
            if (remaining == 0) {
                break;
            }
        }
    }

    return count;
}

