    }
    char[] stack = new char[s.length()];
    int top = -1;
    for (char c : s.toCharArray()) {
        if (top >= 0) {
            char prev = stack[top];
            if (Math.abs(prev - c) == 32 && Character.isLetter(prev) && Character.isLetter(c)) {
                top--;
                continue;
            }
        }
        top++;
        stack[top] = c;
    }
    return new String(stack, 0, top + 1);
}

