public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }

    // Handle the case where low is 0
    if (low == 0) {
        result.add(0);
    }

    // BFS/DFS approach starting from each single digit 1-9
    Queue<Integer> queue = new ArrayDeque<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer(i);
    }

    while (!queue.isEmpty()) {
        int num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add(num);
        }

        int lastDigit = num % 10;
        int multiplier = num * 10;

        // Try adding lastDigit - 1
        if (lastDigit - 1 >= 0) {
            int nextNum = multiplier + (lastDigit - 1);
            if (nextNum > 0 && nextNum <= high) {
                queue.offer(nextNum);
            }
        }

        // Try adding lastDigit + 1
        if (lastDigit + 1 <= 9) {
            int nextNum = multiplier + (lastDigit + 1);
            if (nextNum > 0 && nextNum <= high) {
                queue.offer(nextNum);
            }
        }
    }

    // Sort the result to ensure ascending order
    Collections.sort(result);

    return result;
}

