public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }

    boolean negative = n < 0;
    int absN = negative ? -n : n;

    String str = String.valueOf(absN);
    StringBuilder sb = new StringBuilder();

    if (str.length() <= 3) {
        sb.append(str);
    } else {
        int len = str.length();
        int firstGroupLen = len % 3;
        if (firstGroupLen == 0) {
            firstGroupLen = 3;
        }
        sb.append(str, 0, firstGroupLen);
        for (int i = firstGroupLen; i < len; i += 3) {
            sb.append('.').append(str, i, i + 3);
        }
    }

    if (negative) {
        sb.insert(0, '-');
    }

    return sb.toString();
}

