public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }

    String s = String.valueOf(n);
    char[] chars = s.toCharArray();
    int len = chars.length;

    // Step 1: Find the rightmost character that is smaller than the next character
    int i = len - 2;
    while (i >= 0 && chars[i] >= chars[i + 1]) {
        i--;
    }

    if (i < 0) {
        // The number is in decreasing order, no larger permutation exists
        return -1;
    }

    // Step 2: Find the smallest character to the right of i that is greater than chars[i]
    int j = len - 1;
    while (j > i && chars[j] <= chars[i]) {
        j--;
    }

    // Step 3: Swap chars[i] and chars[j]
    char temp = chars[i];
    chars[i] = chars[j];
    chars[j] = temp;

    // Step 4: Reverse the suffix starting from i+1 to get the smallest suffix
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        char t = chars[left];
        chars[left] = chars[right];
        chars[right] = t;
        left++;
        right--;
    }

    String result = new String(chars);

    // Handle cases where the result might have leading zeros (shouldn't happen for positive n, but just in case)
    // Also check if the result is actually greater than n
    try {
        long val = Long.parseLong(result);
        if (val > n) {
            if (val > Integer.MAX_VALUE) {
                return -1;
            }
            return (int) val;
        }
    } catch (NumberFormatException e) {
        return -1;
    }

    return -1;
}

