    // We choose leftLength digits such that the first is not '0'.
    // Then right half is determined by mirroring.

    // For each position i in 0..leftLength-1:
    //   if i == 0: choices = ["1","6","8","9"]
    //   else if i == leftLength - 1 && n % 2 == 1: choices = ["0","1","8"]
    //   else: choices = ["0","1","6","8","9"]

    // Then when at position leftLength, we construct the full number:
    //   String left = current
    //   String right;
    //   if n is even: right = reverse(left) mapped
    //   if n is odd: right = reverse(left.substring(0, leftLength-1)) mapped

    // Let's implement this with DFS stack.

