    Stack<Integer> depthStack = new Stack<>();
    Stack<String> strStack = new Stack<>();
    depthStack.push(0);
    strStack.push("");

    while (!depthStack.isEmpty()) {
        int depth = depthStack.pop();
        String current = strStack.pop();

        // If we have filled all left positions
        if (depth == (n + 1) / 2) {
            // Construct the full number
            String left = current;
            String full;
            if (n % 2 == 0) {
