            choices = Arrays.asList("1", "6", "8", "9");
        } else if (depth == (n + 1) / 2 - 1 && n % 2 == 1) {
            choices = Arrays.asList("0", "1", "8");
        } else {
            choices = Arrays.asList("0", "1", "6", "8", "9");
        }

        // Push choices in reverse order so that the first choice is processed first
        for (int i = choices.size() - 1; i >= 0; i--) {
            depthStack.push(depth + 1);
            strStack.push(current + choices.get(i));
        }
    }

    return result;
}

public static List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        return new ArrayList<>();
    }

    int[] pairs = {0, 1, 6, 8, 9};
    int[] counterparts = {0, 1, 9, 8, 6};

    List<String> results = new ArrayList<>();
    int halfLength = (n + 1) / 2;

    for (int i = 0; i < Math.pow(5, halfLength); i++) {
        int num = (int) i;
        StringBuilder leftPart = new StringBuilder();
        int temp = num;

        for (int j = 0; j < halfLength; j++) {
            int digit = temp % 5;
            leftPart.append((char) ('0' + pairs[digit]));
            temp /= 5;
        }

        String left = leftPart.toString();
        String right = "";
        int start = (n % 2 == 0) ? left.length() - 1 : left.length() - 2;
        for (int j = start; j >= 0; j--) {
            int digit = left.charAt(j) - '0';
            int idx = -1;
            for (int k = 0; k < pairs.length; k++) {
                if (pairs[k] == digit) {
                    idx = k;
                    break;
                }
            }
            if (idx != -1) {
                right += String.valueOf(counterparts[idx]);
            }
        }

        String result = left + right;

        // For even length, leading zeros are allowed only for the whole number being "00", "01", etc. but we need to check if the first digit is 0 and n > 1
        if (n > 1 && result.charAt(0) == '0') {
            continue;
        }

        results.add(result);
    }

    return results;
}

