public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length < 3) {
        return false;
    }

    if (points.length != 3) {
        return false;
    }

    int[] p1 = points[0];
    int[] p2 = points[1];
    int[] p3 = points[2];

    if (p1 == null || p2 == null || p3 == null) {
        return false;
    }

    if (p1.length < 2 || p2.length < 2 || p3.length < 2) {
        return false;
    }

    int x1 = p1[0], y1 = p1[1];
    int x2 = p2[0], y2 = p2[1];
    int x3 = p3[0], y3 = p3[1];

    // Check if all three points are the same
    if (x1 == x2 && y1 == y2 && x2 == x3 && y2 == y3) {
        return false;
    }

    // Calculate squared distances
    long d12 = (long)(x1 - x2) * (x1 - x2) + (long)(y1 - y2) * (y1 - y2);
    long d13 = (long)(x1 - x3) * (x1 - x3) + (long)(y1 - y3) * (y1 - y3);
    long d23 = (long)(x2 - x3) * (x2 - x3) + (long)(y2 - y3) * (y2 - y3);

    // Check if any two distances are zero (duplicate points)
    if (d12 == 0 || d13 == 0 || d23 == 0) {
        return false;
    }

    // Check collinearity using cross product (area of triangle = 0)
    // 2 * area = |(x2 - x1)(y3 - y1) - (x3 - x1)(y2 - y1)|
    long area = (long)(x2 - x1) * (y3 - y1) - (long)(x3 - x1) * (y2 - y1);

    // If area is zero, points are collinear (not a boomerang)
    return area != 0;
}

