        if (index >= 0 && index < 201) {
            freq[index]++;
        }
    }

    int sum = 0;
    for (int num : nums) {
        int index = num + 100;
        if (index >= 0 && index < 201 && freq[index] == 1 && !counted[index]) {
            sum += num;
            counted[index] = true;
        }
    }

    return sum;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }

    java.util.Set<Integer> uniqueElements = new java.util.HashSet<>();
    java.util.Set<Integer> seenSet = new java.util.HashSet<>();
    java.util.Set<Integer> duplicateSet = new java.util.HashSet<>();

    for (int num : nums) {
        if (seenSet.contains(num)) {
            duplicateSet.add(num);
        }
        seenSet.add(num);
    }

    for (int num : seenSet) {
        if (!duplicateSet.contains(num)) {
            uniqueElements.add(num);
        }
    }

    int sum = 0;
    for (int num : uniqueElements) {
        sum += num;
    }

    return sum;
}

