public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = i; // worst case: all ones
        for (int j = 1; j * j <= i; j++) {
            int remainder = i - j * j;
            if (dp[remainder] + 1 < dp[i]) {
                dp[i] = dp[remainder] + 1;
            }
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }

    // DP: dp[i] = minimum number of perfect squares to sum to i
    int[] dp = new int[n + 1];
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        dp[i] = i; // worst case: all 1s
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            if (dp[i - square] + 1 < dp[i]) {
                dp[i] = dp[i - square] + 1;
            }
        }
    }

    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = i;
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }

    int[] dp = new int[n + 1];
    java.util.Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        int j = 1;
        while (j * j <= i) {
            if (dp[i - j * j] != Integer.MAX_VALUE) {
                dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
            }
            j++;
        }
    }

    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }

    int[] dp = new int[n + 1];
    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        int j = 1;
        while (j * j <= i) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
            j++;
        }
    }

    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    StringBuilder result = new StringBuilder();
    String[] words = s.split(" ", -1);
    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        StringBuilder reversed = new StringBuilder(word).reverse();
        result.append(reversed);
        if (i < words.length - 1) {
            result.append(" ");
        }
    }
    return result.toString();
}

